696	export function getEditorsToPropagate(
697	  editor: LexicalEditor,
698	): Array<LexicalEditor> {
699	  const editorsToPropagate: LexicalEditor[] = [];
700	  for (
701	    let currentEditor: LexicalEditor | null = editor;
