  TCommand extends LexicalCommand<unknown>,
>(
  editor: LexicalEditor,
  type: TCommand,
  payload: CommandPayloadType<TCommand>,
  // The editor that originally dispatched the command. This is passed as the
  // second argument to every command listener (including those on ancestor
  // editors) and is only distinct from `editor` when propagation to an
  // ancestor was deferred because that ancestor was updating (see below).
  dispatchEditor: LexicalEditor = editor,
): boolean {
  const editors = getEditorsToPropagate(editor);

  // Commands dispatched by a nested editor propagate synchronously up through
  // its ancestors. If an ancestor is in the middle of an update, however, we
  // must not run its command listeners inline as that would run an update
  // within an update (committing early and potentially corrupting the
  // nodeMap). Instead we run the listeners we safely can now and defer the
  // remaining propagation until that ancestor's update completes.
  let editorsLength = editors.length;
  let deferredEditor: null | LexicalEditor = null;
  for (let e = 1; e < editors.length; e++) {
    if (editors[e]._updating) {
      deferredEditor = editors[e];
      editorsLength = e;
      break;
    }
  }

  for (let i = 4; i >= 0; i--) {
    for (let e = 0; e < editorsLength; e++) {
      const currentEditor = editors[e];
      const commandListeners = currentEditor._commands;
      const listenerInPriorityOrder = commandListeners.get(type);

      if (listenerInPriorityOrder !== undefined) {
        const listenersSet = listenerInPriorityOrder[i];

        if (listenersSet !== undefined) {
          const listeners = Array.from(listenersSet);
          const listenersLength = listeners.length;

          let returnVal = false;
          updateEditorSync(currentEditor, () => {
            for (let j = 0; j < listenersLength; j++) {
              if (listeners[j](payload, dispatchEditor)) {
                returnVal = true;
                return;
              }
            }
          });
          if (returnVal) {
            return returnVal;
          }
        }
      }
    }
  }

  if (deferredEditor !== null) {
    const parentEditor = deferredEditor;
    parentEditor._deferred.push(() => {
      triggerCommandListeners(parentEditor, type, payload, dispatchEditor);
    });
  }

  return false;
