import {
  buildEditorFromExtensions,
  NestedEditorExtension,
} from '@lexical/extension';
import {createCommand, $getEditor} from 'lexical';
import {describe, expect, test} from 'vitest';

const TEST_COMMAND = createCommand<undefined>('TEST_COMMAND');

describe('scratch', () => {
  test('sync propagation', () => {
    using parent = buildEditorFromExtensions({name: 'parent'});
    const child = parent.read(() =>
      buildEditorFromExtensions({
        dependencies: [NestedEditorExtension],
        name: 'child',
      }),
    );
    const calls: string[] = [];
    child.registerCommand(
      TEST_COMMAND,
      () => {
        calls.push(`child active=${$getEditor() === child ? 'child' : 'parent'}`);
        return false;
      },
      0,
    );
    parent.registerCommand(
      TEST_COMMAND,
      (payload, ed) => {
        calls.push(
          `parent editorArg=${ed === child ? 'child' : ed === parent ? 'parent' : '?'} active=${$getEditor() === parent ? 'parent' : 'child'}`,
        );
        return false;
      },
      0,
    );
    const result = child.dispatchCommand(TEST_COMMAND, undefined);
    console.log('SYNC result=', result, 'calls=', JSON.stringify(calls));
    expect(calls).toEqual([
      'child active=child',
      'parent editorArg=child active=parent',
    ]);
    expect(result).toBe(false);
  });

  test('during parent update - deferred', () => {
    using parent = buildEditorFromExtensions({name: 'parent'});
    const child = parent.read(() =>
      buildEditorFromExtensions({
        dependencies: [NestedEditorExtension],
        name: 'child',
      }),
    );
    let childCount = 0;
    let parentCount = 0;
    let parentEditorArg = '?';
    let parentActive = '?';
    child.registerCommand(
      TEST_COMMAND,
      () => {
        childCount++;
        return false;
      },
      0,
    );
    parent.registerCommand(
      TEST_COMMAND,
      (payload, ed) => {
        parentCount++;
        parentEditorArg = ed === child ? 'child' : ed === parent ? 'parent' : '?';
        parentActive = $getEditor() === parent ? 'parent' : 'child';
        return false;
      },
      0,
    );
    let result: boolean | undefined;
    parent.update(() => {
      result = child.dispatchCommand(TEST_COMMAND, undefined);
      console.log(
        'DURING result=',
        result,
        'childCount=',
        childCount,
        'parentCount=',
        parentCount,
      );
      expect(result).toBe(false);
      expect(childCount).toBe(1);
      expect(parentCount).toBe(0);
    });
    console.log(
      'AFTER childCount=',
      childCount,
      'parentCount=',
      parentCount,
      'editorArg=',
      parentEditorArg,
      'active=',
      parentActive,
    );
    expect(childCount).toBe(1);
    expect(parentCount).toBe(1);
    expect(parentEditorArg).toBe('child');
    expect(parentActive).toBe('parent');
