 * temp verification
 */
import {
  buildEditorFromExtensions,
  NestedEditorExtension,
} from '@lexical/extension';
import {$getEditor, createCommand} from 'lexical';
import {describe, expect, test} from 'vitest';

const CMD = createCommand<undefined>('CMD');

function setup() {
  const parent = buildEditorFromExtensions({name: 'parent'});
  const child = parent.read(() =>
    buildEditorFromExtensions({
      dependencies: [NestedEditorExtension],
      name: 'child',
    }),
  );
  return {child, parent};
}

describe('verify all requirements', () => {
  test('req1-3: sync propagation, order, editorArg, $getEditor', () => {
    const {child, parent} = setup();
    const log: string[] = [];
    child.registerCommand(
      CMD,
      () => {
        log.push(`child($getEditor=${$getEditor() === child ? 'child' : 'parent'})`);
        return false;
      },
      0,
    );
    parent.registerCommand(
      CMD,
      (_p, ed) => {
        log.push(
          `parent(editorArg=${ed === child ? 'child' : 'parent'},$getEditor=${$getEditor() === parent ? 'parent' : 'child'})`,
        );
        return false;
      },
      0,
    );
    const result = child.dispatchCommand(CMD, undefined);
    expect(log).toEqual([
      'child($getEditor=child)',
      'parent(editorArg=child,$getEditor=parent)',
    ]);
    expect(result).toBe(false);
  });

  test('req2: returns true if a parent handler returns true (sync)', () => {
    const {child, parent} = setup();
    child.registerCommand(CMD, () => false, 0);
    parent.registerCommand(CMD, () => true, 0);
    expect(child.dispatchCommand(CMD, undefined)).toBe(true);
  });

  test('req4+5: deferred during parent update, fires exactly once after', async () => {
    const {child, parent} = setup();
    let childCount = 0;
    let parentCount = 0;
    let parentArg = '?';
    let parentActive = '?';
    child.registerCommand(
      CMD,
      () => {
        childCount++;
        return false;
      },
      0,
    );
    parent.registerCommand(
      CMD,
      (_p, ed) => {
        parentCount++;
        parentArg = ed === child ? 'child' : 'parent';
        parentActive = $getEditor() === parent ? 'parent' : 'child';
        return false;
      },
      0,
    );
    let ret: boolean | undefined;
    parent.update(() => {
      ret = child.dispatchCommand(CMD, undefined);
      // req4: child ran, parent NOT yet, returns false
      expect(childCount).toBe(1);
      expect(parentCount).toBe(0);
      expect(ret).toBe(false);
    });
    // flush the parent's async commit / deferred callbacks
    await Promise.resolve();
    await Promise.resolve();
    // req5: parent handler fired exactly once, with child as editorArg
    expect(childCount).toBe(1);
    expect(parentCount).toBe(1);
    expect(parentArg).toBe('child');
    expect(parentActive).toBe('parent');
  });
});
